	Sprint      string            `json:"sprint"`
	Review      VerificationStage `json:"review"`
	Smoke       VerificationStage `json:"smoke"`
	Assessment  OverallAssessment `json:"overall_assessment"`
	NextAction  string            `json:"next_action"`
