	writeJSON(t, path, bad)
	if _, err := LoadFlowState(root, sp); !errors.Is(err, ErrFlowStateMalformed) {
		t.Fatalf("unsupported stage err = %v", err)
	}
	writeFileContent(t, filepath.Dir(path), string(original), filepath.Base(path))

